INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers ensure effective communication within their organization?', 'By limiting communication channels', 'By establishing clear communication protocols and fostering an open dialogue', 'By ignoring staff feedback', 'By reducing information sharing', 'B', 'Effective organizational communication requires clear, standardized protocols plus open, two-way dialogue, per nursing management and organizational-behaviour theory. Limiting channels, ignoring feedback, or reducing information sharing all impair communication and are therefore wrong.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of quality improvement (QI) initiatives in health systems management?', 'To ignore performance issues', 'To systematically enhance processes and outcomes through continuous evaluation and improvement', 'To reduce staff involvement in improvement efforts', 'To limit the application of best practices', 'B', 'Quality improvement systematically enhances processes and outcomes through continuous evaluation and iterative change (e.g. PDSA cycles), per MOH Kenya Quality Improvement frameworks. Ignoring performance, reducing staff involvement, or limiting best-practice use all contradict the purpose of QI.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address the challenges of health disparities in their communities?', 'By ignoring social and economic factors affecting health', 'By implementing strategies to reduce barriers and improve access to care for underserved populations', 'By increasing healthcare costs for disadvantaged groups', 'By limiting outreach programs', 'B', 'Health disparities are reduced by implementing strategies that lower barriers and improve access for underserved populations, consistent with Kenya''s Universal Health Coverage equity agenda. Ignoring social/economic determinants, raising costs for disadvantaged groups, or limiting outreach worsen disparities.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the primary purpose of strategic planning in health systems management?', 'To limit organizational growth', 'To outline long-term goals and define the path to achieve them', 'To reduce patient care quality', 'To ignore market trends', 'B', 'Strategic planning defines an organization''s long-term goals and the roadmap to achieve them, per nursing management and health-systems planning theory. It does not limit growth, reduce care quality, or ignore market trends, so those distractors are wrong.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers use cost-benefit analysis to make decisions?', 'By ignoring financial implications', 'By comparing the costs of an intervention with its expected benefits to determine value', 'By increasing operational costs', 'By reducing the scope of analysis', 'B', 'Cost-benefit analysis compares the costs of an intervention with its expected benefits to determine value and guide resource allocation, a standard health-economics decision tool. Ignoring financial implications, increasing costs, or narrowing scope defeat the analysis and are incorrect.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of a health systems manager in crisis management?', 'To ignore potential crises', 'To develop and implement strategies for effective response and recovery', 'To reduce communication during crises', 'To limit the involvement of staff', 'B', 'In crisis/disaster management the manager''s role is to develop and implement strategies for effective response and recovery, per WHO and Kenya disaster-management/emergency-preparedness guidance. Ignoring crises, cutting communication, or limiting staff involvement undermine response and are wrong.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers improve patient throughput in an emergency department?', 'By increasing patient wait times', 'By optimizing workflow and resource allocation to reduce delays', 'By limiting staff training', 'By ignoring patient flow data', 'B', 'Emergency-department throughput improves by optimizing workflow and resource allocation to reduce delays, per operations-management principles applied in health-systems management. Increasing wait times, limiting training, or ignoring flow data all worsen throughput.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the significance of stakeholder engagement in health systems management?', 'To limit input from key stakeholders', 'To incorporate feedback and perspectives from various stakeholders into decision-making processes', 'To reduce collaboration with external parties', 'To increase organizational silos', 'B', 'Stakeholder engagement incorporates feedback and perspectives from diverse stakeholders into decision-making, improving buy-in, legitimacy and outcomes, per governance and leadership theory. Limiting input, reducing collaboration, or increasing silos are the opposite of engagement.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address the challenge of high staff turnover?', 'By increasing staff workloads', 'By implementing retention strategies such as competitive compensation and professional development opportunities', 'By reducing staff engagement', 'By ignoring exit feedback', 'B', 'High staff turnover is countered by retention strategies such as competitive compensation and professional-development opportunities, per human-resource-management theory in nursing. Increasing workloads, reducing engagement, or ignoring exit feedback increase turnover and are wrong.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What role does patient-centered technology play in health systems management?', 'To reduce patient engagement', 'To enhance patient experience and communication through digital tools', 'To limit access to healthcare information', 'To increase administrative burden', 'B', 'Patient-centered technology enhances patient experience and communication through digital tools, supporting the WHO information/technology building block. Reducing engagement, limiting access to information, or increasing administrative burden contradict its purpose.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers ensure the effective use of telemedicine?', 'By ignoring technological advancements', 'By integrating telemedicine into existing care models and ensuring access and usability', 'By limiting telemedicine services', 'By reducing training for telemedicine platforms', 'B', 'Effective telemedicine requires integrating it into existing care models while ensuring access and usability, per Kenya''s digital-health strategy and WHO guidance. Ignoring technology, limiting services, or reducing training prevent effective telemedicine and are wrong.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of data security on health systems management?', 'To increase the risk of data breaches', 'To protect sensitive patient information and maintain trust', 'To limit access to electronic health records', 'To reduce compliance with regulations', 'B', 'Data security protects sensitive patient information and maintains trust, aligning with Kenya''s Data Protection Act (2019) and professional confidentiality duties. Increasing breach risk, limiting legitimate EHR access, or reducing regulatory compliance are harms, not impacts of good data security.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers leverage financial incentives to improve performance?', 'By reducing financial rewards', 'By linking incentives to performance metrics and outcomes to motivate staff', 'By ignoring performance results', 'By limiting bonus opportunities', 'B', 'Financial incentives improve performance when linked to defined performance metrics and outcomes, motivating staff, per performance-management and motivation theory. Reducing rewards, ignoring results, or limiting bonuses would not leverage incentives and are wrong.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of benchmarking in enhancing healthcare service quality?', 'To ignore industry standards', 'To compare performance against best practices and identify areas for improvement', 'To reduce the use of quality measures', 'To limit data analysis', 'B', 'Benchmarking compares an organization''s performance against best practices/industry standards to identify areas for improvement, a standard continuous-quality-improvement method. Ignoring standards, reducing quality measures, or limiting data analysis are the opposite of benchmarking.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers utilize patient outcome data to drive quality improvement?', 'By ignoring outcome measures', 'By analyzing data to identify trends and areas for enhancement', 'By reducing the focus on patient outcomes', 'By limiting the use of data in decision-making', 'B', 'Patient-outcome data drives quality improvement when analyzed to identify trends and areas for enhancement, per MOH quality-improvement and monitoring/evaluation frameworks. Ignoring outcome measures, reducing focus on outcomes, or limiting data use defeat data-driven QI.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the importance of having a comprehensive risk management plan in a healthcare organization?', 'To increase exposure to risks', 'To identify, assess, and mitigate potential risks to patient safety and organizational operations', 'To limit safety protocols', 'To reduce staff involvement in risk management', 'B', 'A comprehensive risk-management plan identifies, assesses and mitigates potential risks to patient safety and organizational operations, per patient-safety and clinical-governance standards. Increasing exposure, limiting safety protocols, or reducing staff involvement defeat the purpose.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers foster interprofessional collaboration?', 'By promoting siloed work environments', 'By creating opportunities for teamwork and communication among different healthcare professionals', 'By limiting interaction between disciplines', 'By reducing joint training sessions', 'B', 'Interprofessional collaboration is fostered by creating opportunities for teamwork and communication among different professionals, per the WHO Framework for Interprofessional Education and Collaborative Practice. Promoting silos, limiting interaction, or reducing joint training block collaboration.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of patient experience surveys in health systems management?', 'To ignore patient feedback', 'To gather insights into patient perceptions and identify areas for service improvement', 'To limit patient involvement in care assessment', 'To reduce communication with patients', 'B', 'Patient-experience surveys gather insights into patient perceptions and identify areas for service improvement, a core QI feedback mechanism in MOH quality standards. Ignoring feedback, limiting patient involvement, or reducing communication contradict their purpose.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address the challenge of increasing healthcare costs?', 'By reducing the quality of care', 'By implementing cost-control measures and improving operational efficiency', 'By limiting patient access to services', 'By ignoring financial management', 'B', 'Rising healthcare costs are addressed by implementing cost-control measures and improving operational efficiency, per health-financing management principles, without sacrificing quality or access. Reducing care quality, limiting access, or ignoring financial management are unacceptable and wrong.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the significance of performance evaluations in health systems management?', 'To limit staff feedback', 'To assess staff performance, identify strengths and weaknesses, and guide professional development', 'To reduce accountability', 'To ignore performance metrics', 'B', 'Performance evaluations assess staff performance, identify strengths and weaknesses, and guide professional development, per human-resource-management theory in nursing leadership. Limiting feedback, reducing accountability, or ignoring metrics are the opposite of a sound appraisal system.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers use patient flow data to improve hospital operations?', 'By ignoring patient flow trends', 'By analyzing data to optimize resource allocation and reduce bottlenecks', 'By increasing patient wait times', 'By limiting the use of flow data', 'B', 'Patient-flow data is used to optimize resource allocation and reduce bottlenecks, improving hospital operations per operations-management principles. Ignoring flow trends, increasing wait times, or limiting data use undermine operational efficiency.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of clinical pathways in health systems management?', 'To ignore evidence-based practices', 'To standardize care processes and improve patient outcomes through evidence-based protocols', 'To reduce adherence to best practices', 'To limit the use of clinical guidelines', 'B', 'Clinical pathways standardize care processes using evidence-based protocols to improve outcomes and reduce unwarranted variation, per quality-of-care and clinical-governance standards. Ignoring evidence, reducing adherence to best practice, or limiting guideline use defeat their function.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers enhance patient safety culture within their organization?', 'By reducing safety training', 'By promoting a culture of transparency, accountability, and continuous learning', 'By limiting staff involvement in safety initiatives', 'By ignoring safety concerns', 'B', 'A patient-safety culture is enhanced by promoting transparency, accountability, and continuous learning (a just culture where errors are reported and learned from), per the WHO patient-safety framework reflected in Kenya''s Quality of Care guidelines. Reducing training, limiting involvement, or ignoring concerns weaken safety.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers ensure compliance with healthcare regulations?', 'By ignoring regulatory requirements', 'By implementing policies and procedures that adhere to regulatory standards and conducting regular audits', 'By reducing staff training on regulations', 'By limiting compliance monitoring', 'B', 'Regulatory compliance is ensured by implementing policies and procedures aligned to regulatory standards and verifying adherence through regular audits, per Kenya HSM and quality-assurance principles. Ignoring requirements, reducing training, or limiting monitoring create non-compliance.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What role does patient advocacy play in health systems management?', 'To limit patient involvement in care decisions', 'To ensure that patient rights are protected and their voices are heard in care planning and decisionmaking', 'To reduce patient support services', 'To ignore patient feedback', 'B', 'Patient advocacy ensures patient rights are protected and their voices are heard in care planning and decision-making, consistent with the Kenya Patients'' Rights Charter and NCK professional ethics. Limiting involvement, reducing support services, or ignoring feedback are contrary to advocacy.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers utilize workflow analysis to improve efficiency?', 'By ignoring workflow bottlenecks', 'By identifying and addressing inefficiencies and streamlining processes', 'By increasing administrative tasks', 'By reducing staff involvement in process improvement', 'B', 'Workflow analysis improves efficiency by identifying and addressing inefficiencies and streamlining processes, a core operations/HSM quality-improvement principle. Ignoring bottlenecks, increasing administrative tasks, or reducing staff involvement work against efficiency.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of leadership development programs on health systems management?', 'To limit career growth opportunities', 'To enhance leadership skills, improve decision-making, and support organizational goals', 'To reduce staff engagement', 'To ignore leadership training', 'B', 'Leadership development programs enhance leadership skills, improve decision-making, and support organizational goals, per nursing leadership/management theory in HSM. Limiting career growth, reducing engagement, or ignoring training are opposite outcomes and therefore wrong.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address healthcare disparities through policy changes?', 'By ignoring social determinants of health', 'By implementing policies that address social determinants and promote equitable access to care', 'By limiting support for underserved populations', 'By reducing funding for equity initiatives', 'B', 'Healthcare disparities are reduced by policies that address social determinants of health and promote equitable access to care, consistent with Kenya''s UHC and health-equity policy goals. Ignoring determinants, limiting support, or cutting equity funding perpetuate disparities.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of patient navigation programs in health systems management?', 'To limit patient access to services', 'To assist patients in navigating the healthcare system and accessing necessary care and resources', 'To reduce patient engagement', 'To ignore care coordination', 'B', 'Patient navigation programs assist patients in navigating the healthcare system and accessing necessary care and resources, improving continuity and outcomes (HSM/care-coordination principle). Limiting access, reducing engagement, or ignoring coordination contradict the program''s purpose.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers use risk stratification to improve patient care?', 'By ignoring patient risk levels', 'By categorizing patients based on their risk levels and tailoring interventions accordingly', 'By reducing the use of risk assessments', 'By limiting patient care planning', 'B', 'Risk stratification categorizes patients by risk level so interventions can be tailored accordingly, improving efficiency and outcomes (population-health/HSM principle). Ignoring risk levels, reducing assessments, or limiting care planning defeat the approach.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of healthcare mergers and acquisitions on health systems management?', 'To increase operational complexity and integration challenges', 'To consolidate resources and enhance service delivery', 'To reduce organizational efficiency', 'To limit patient access to services', 'B', 'Healthcare mergers and acquisitions (M&A) combine two or more health organisations with the primary objective of consolidating resources — staff, finances, equipment, infrastructure — and enhancing service delivery through economies of scale, reduced duplication, and improved care coordination (option B). While M&A can create short-term integration challenges (option A), these are transitional implementation difficulties, not the principal impact or purpose. Reducing organisational efficiency (option C) and limiting patient access (option D) are contrary to the goals of M&A. In single-best-answer examinations, the primary organisational benefit and purpose is the correct answer.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers use evidence-based practice to improve care quality?', 'By ignoring clinical research', 'By incorporating the best available evidence into clinical decision-making and care protocols', 'By reducing the use of clinical guidelines', 'By limiting research integration', 'B', 'Evidence-based practice improves care quality by incorporating the best available evidence into clinical decision-making and care protocols, per NCK curriculum and EBP principles. Ignoring research, reducing guideline use, or limiting research integration are the opposite of EBP.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of health systems managers in implementing patient safety initiatives?', 'To ignore safety protocols', 'To develop and enforce safety protocols, conduct training, and monitor compliance', 'To reduce safety oversight', 'To limit staff involvement in safety efforts', 'B', 'Managers implement patient-safety initiatives by developing and enforcing safety protocols, conducting training, and monitoring compliance, per patient-safety and quality-assurance frameworks. Ignoring protocols, reducing oversight, or limiting staff involvement undermine safety.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address the challenge of healthcare workforce shortages?', 'By ignoring workforce planning', 'By implementing recruitment and retention strategies, and optimizing workforce utilization', 'By reducing staff training programs', 'By limiting career advancement opportunities', 'B', 'Workforce shortages are addressed by implementing recruitment and retention strategies and optimizing workforce utilization, per Kenya''s Human Resources for Health strategy. Ignoring planning, reducing training, or limiting advancement worsen shortages.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the significance of a balanced scorecard in health systems management?', 'To focus solely on financial performance', 'To provide a comprehensive view of organizational performance through financial and non-financial metrics', 'To limit performance measurement', 'To reduce focus on strategic objectives', 'B', 'The balanced scorecard provides a comprehensive view of organizational performance through both financial and non-financial metrics (financial, customer, internal process, learning/growth), per management theory. Focusing solely on finance, limiting measurement, or reducing strategic focus contradict its design.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers use patient-centered care models to enhance service delivery?', 'By focusing on provider needs over patient needs', 'By designing care processes that prioritize patient preferences, values, and needs', 'By reducing patient engagement in care planning', 'By ignoring patient feedback', 'B', 'Patient-centered care models enhance service delivery by designing care processes that prioritize patient preferences, values, and needs, a core NCK/quality-of-care principle. Prioritizing provider needs, reducing engagement, or ignoring feedback are the antithesis of patient-centered care.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of health systems managers in fostering a culture of innovation?', 'To limit new ideas', 'To encourage creativity, support experimentation, and implement innovative solutions', 'To reduce research and development efforts', 'To ignore emerging trends', 'B', 'Fostering a culture of innovation means encouraging creativity, supporting experimentation, and implementing innovative solutions, per leadership/management theory. Limiting new ideas, reducing R&D, or ignoring emerging trends stifle innovation and are wrong.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address the needs of an aging population?', 'By ignoring geriatric care', 'By developing programs and services tailored to the specific needs of older adults', 'By reducing support for elderly care', 'By limiting research on aging', 'B', 'The needs of an aging population are addressed by developing programs and services tailored to the specific needs of older adults, per HSM and community-health geriatric-care principles. Ignoring geriatric care, reducing elderly support, or limiting research neglect this population.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers use process improvement methodologies to enhance care quality?', 'By ignoring best practices', 'By applying methodologies such as Lean or Six Sigma to streamline processes and reduce inefficiencies', 'By reducing focus on process optimization', 'By limiting staff involvement in improvement efforts', 'B', 'Process-improvement methodologies such as Lean and Six Sigma streamline processes and reduce inefficiencies to enhance care quality, per quality-improvement/HSM practice. Ignoring best practices, reducing optimization focus, or limiting staff involvement defeat the methodologies.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of strategic planning in health systems management?', 'To focus solely on day-to-day operations', 'To set long-term goals, allocate resources, and guide decision-making to achieve organizational objectives', 'To ignore future trends', 'To reduce focus on organizational growth', 'B', 'Strategic planning sets long-term goals, allocates resources, and guides decision-making to achieve organizational objectives, per management theory. Focusing solely on day-to-day operations, ignoring future trends, or reducing growth focus contradict strategic (as opposed to operational) planning.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers ensure effective care coordination across different providers?', 'By limiting communication between providers', 'By implementing integrated care models and communication systems to facilitate information sharing', 'By reducing care transitions', 'By ignoring interdisciplinary collaboration', 'B', 'Effective care coordination is ensured by implementing integrated care models and communication systems that facilitate information sharing across providers, per HSM/continuity-of-care principles. Limiting communication, reducing safe transitions, or ignoring interdisciplinary collaboration fragment care.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of patient engagement on health systems management?', 'To reduce patient involvement in care decisions', 'To improve health outcomes and satisfaction by involving patients in their care planning and decision-making', 'To ignore patient preferences', 'To limit patient education efforts', 'B', 'Patient engagement improves health outcomes and satisfaction by involving patients in their care planning and decision-making, a patient-centered care principle. Reducing involvement, ignoring preferences, or limiting patient education are opposite effects and wrong.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers leverage data analytics to improve decision-making?', 'By ignoring data-driven insights', 'By analyzing healthcare data to identify trends, predict outcomes, and inform strategic decisions', 'By reducing data collection efforts', 'By limiting the use of technology', 'B', 'Data analytics improves decision-making by analyzing healthcare data to identify trends, predict outcomes, and inform strategic decisions, per HSM/health-information-systems practice. Ignoring insights, reducing data collection, or limiting technology use undermine data-driven management.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What role does community health integration play in health systems management?', 'To limit community involvement in healthcare', 'To enhance collaboration between healthcare providers and community resources, addressing broader health needs', 'To reduce outreach efforts', 'To ignore local health issues', 'B', 'Community health integration enhances collaboration between providers and community resources to address broader determinants of health, per Kenya Community Health Strategy/WHO health systems building blocks. Options A, C and D describe neglecting or limiting community involvement, which contradicts the integration goal.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address healthcare fraud and abuse?', 'By ignoring suspicious activities', 'By implementing robust monitoring, auditing, and compliance programs', 'By reducing oversight', 'By limiting staff training on fraud prevention', 'B', 'Healthcare fraud and abuse are countered by robust monitoring, auditing and compliance programs that ensure accountability, per HSM governance principles and Kenya public financial-management controls. Ignoring activity, reducing oversight or limiting training (A, C, D) would increase fraud risk.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of patient privacy regulations on health systems management?', 'To reduce focus on patient confidentiality', 'To ensure the protection of patient information and compliance with privacy laws and regulations', 'To limit data security measures', 'To ignore patient consent', 'B', 'Privacy regulations require protecting patient information and complying with data-protection law (Kenya Data Protection Act 2019; NCK Code of Conduct confidentiality). Reducing confidentiality, limiting security or ignoring consent (A, C, D) violate these legal duties.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers improve patient flow within healthcare facilities?', 'By ignoring bottlenecks in care delivery', 'By optimizing processes, scheduling, and resource allocation to streamline patient flow and reduce wait times', 'By increasing patient wait times', 'By limiting staff involvement in patient flow management', 'B', 'Patient flow is improved by optimizing processes, scheduling and resource allocation to reduce wait times, per health-services operations management. Ignoring bottlenecks, increasing wait times or limiting staff involvement (A, C, D) worsen flow.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of telehealth in modern health systems management?', 'To limit access to care', 'To provide remote healthcare services, improve access, and enhance patient convenience', 'To reduce technology use', 'To ignore virtual care options', 'B', 'Telehealth provides remote services, improving access and patient convenience, consistent with Kenya''s Digital Health Act/eHealth strategy. Limiting access, reducing technology or ignoring virtual care (A, C, D) contradict telehealth''s purpose.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers support interdisciplinary collaboration?', 'By limiting team interactions', 'By promoting communication and collaboration among diverse healthcare professionals to improve patient care', 'By reducing team meetings', 'By ignoring the benefits of diverse perspectives', 'B', 'Interdisciplinary collaboration is supported by promoting communication among diverse professionals to improve patient care, per WHO interprofessional practice framework. Limiting interactions, reducing meetings or ignoring diverse perspectives (A, C, D) undermine teamwork.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of patient satisfaction surveys in health systems management?', 'To limit feedback collection', 'To gather patient feedback on their care experience and identify areas for improvement', 'To ignore patient opinions', 'To reduce focus on service quality', 'B', 'Patient satisfaction surveys gather feedback on the care experience to identify areas for improvement, a core continuous-quality-improvement tool in HSM. Limiting feedback, ignoring opinions or reducing quality focus (A, C, D) defeat the survey''s purpose.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address the challenges of chronic disease management?', 'By ignoring chronic conditions', 'By implementing comprehensive care plans, patient education, and regular monitoring to manage chronic diseases effectively', 'By reducing support for chronic disease programs', 'By limiting patient engagement in care management', 'B', 'Chronic disease is managed through comprehensive care plans, patient education and regular monitoring, per Kenya NCD management guidelines and WHO chronic-care model. Ignoring conditions, cutting programs or limiting engagement (A, C, D) worsen outcomes.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Qualities of good entrepreneurs include;', 'Conformists, risk takers, critical thinkers', 'Critical thinkers, tolerant, conformists', 'Conformists, tolerant, risk takers', 'Critical thinkers, risk takers, tolerant', 'D', 'Per entrepreneurship principles in the NCK health-systems-management syllabus, good entrepreneurs are critical/creative thinkers, risk takers and tolerant of ambiguity and failure; they are innovators, NOT conformists. Only option D excludes ''conformists'' and lists the three genuine traits, so options A, B and C are wrong for including conformism.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is an advantage of Functional Nursing care modality?', 'There is specialization', 'It can be monotonous hence boredom', 'Client may become impersonal', 'There is little avenue for development', 'A', 'Per nursing management texts (Marquis & Huston), in the functional/task-oriented care modality each nurse performs specific assigned tasks, giving specialization and efficiency, which is its chief advantage. Monotony/boredom (B), impersonal/fragmented care (C) and little avenue for professional development (D) are recognised DISADVANTAGES, so only A is an advantage.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is a type of nursing audit:', 'Performance appraisal', 'Job analysis', 'Job description', 'Operational audit', 'D', 'Per nursing quality-assurance texts, nursing audits are classified as structure, process and outcome audits and by scope include operational (concurrent/process) audits, so operational audit (D) is a type of nursing audit. Performance appraisal, job analysis and job description (A, B, C) are human-resource functions, not audits.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Factors to remember while purchasing commodities include the following _____________?', 'Quantity & payment discounts', 'Locality of the supplier', 'Gender of supplier', 'Primary contract', 'A', 'Per procurement/supplies-management principles in the NCK health-systems syllabus, factors to consider when purchasing include quantity and payment (cash/trade) discounts, quality, price and supplier reliability. Gender of the supplier (C) is irrelevant/discriminatory, and mere locality (B) or an unexplained ''primary contract'' (D) are not core purchasing criteria, so A is correct.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following describes inventory control.', 'It is the full range of activities related to purchasing goods, services and works', 'It is the process required to supply equipment , material , service and other resources needed to carry out a project', 'It is concerned with planning, organizing and controlling the flow of materials from their initial purchase through internal operations to the service point through distribution.', 'It means stocking adequate number and kind of stores, so that the materials are available whenever required and wherever required.', 'D', 'Per health-systems/supplies management texts, inventory control means keeping adequate numbers and kinds of stock so materials are available whenever and wherever required, avoiding both stock-outs and overstocking (option D). Option A defines procurement, B defines project supply/logistics, and C defines materials management, so D best defines inventory control.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is the correct sequence of the procurement process?', 'Planning, Documentation, Product evaluation, Awarded and Administration, Inspection and Delivery', 'Planning, Awarded and Administration, Documentation, Product evaluation, Inspection and Delivery', 'Planning, Documentation, Awarded and Administration, Inspection and Delivery, Product evaluation', 'Planning, Documentation, Product evaluation, Awarded and , Inspection and Delivery, Administration', 'A', 'Per public procurement practice (PPAD-based) in the NCK syllabus, the logical sequence is planning, documentation (tender documents), product/bid evaluation, award and contract administration, then inspection and delivery/acceptance. Only option A places evaluation before award and delivery last; B, C and D disorder award, evaluation or delivery.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Tactical plans in an organisation', 'Focus on single daily action', 'Are concerned on how to implement operational plans', 'Are of intermediate time frame', 'Are mainly developed from the major organisation goals', 'C', 'Per nursing management/planning theory (Marquis & Huston), tactical plans are of intermediate time frame, prepared by middle management to translate strategic plans into departmental action. Plans developed directly from major organisational goals are strategic (D) and single daily actions are operational (A), so C describes tactical plans.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Feedback to subordinate from nurse managers;', 'Should be given in private always', 'Should be done daily', 'Should be both objective and subjective', 'Should have negative comments last.', 'C', 'Per nursing supervision/feedback principles (Marquis & Huston), effective feedback is balanced, using both objective (measurable) and subjective information, and is timely and constructive. It need not always be given in private (A), daily (B) or always end with negatives (D), so C is the best-supported statement.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following theorist emphasised on the use of rules, regulations and policies to govern employees.', 'Frederic Taylor', 'Max Weber', 'Henri Fayol', 'Douglas McGregor', 'B', 'Max Weber''s bureaucratic theory of management emphasises rules, regulations, hierarchy and impersonal policies to govern employees (Marquis & Huston, Leadership Roles and Management Functions in Nursing). Taylor (A) is scientific management, Fayol (C) administrative principles, and McGregor (D) Theory X/Y, so B is correct.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Principles of customer care that you can utilize include;', 'Understanding what you do, ensuring you are compensated for what you do', 'Finishing your tasks, being happy with your job', 'Understanding your customer needs, Ensuring division of labour', 'Being hospitable, proper time management', 'D', 'Per health-service customer-care/quality guidelines used in Kenyan facilities, customer-care principles centre on serving clients courteously and efficiently; being hospitable and practising good time management (D) are genuine customer-care behaviours. The distractors emphasise self-interest (compensation, own happiness) or internal operations (division of labour) rather than client focus.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Ascribed status includes being;', 'A politician', 'An eldery', 'A businessman', 'A nurse', 'B', 'Per behavioural science/sociology texts used in Kenyan nursing training, ascribed status is assigned at birth or acquired involuntarily (e.g. age/being elderly, sex, race), so ''an elderly'' (B) is ascribed. Politician, businessman and nurse (A, C, D) are achieved statuses earned through effort, so B is correct.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are elements of an advocacy objective', 'Policy actor, the advocates, timeline', 'Policy action, the advocates, budget', 'Policy actor, policy action, timeline', 'Resources, advocacy issue, networks', 'C', 'Per the SMART advocacy-objective framework (community health/advocacy guidelines), an advocacy objective specifies WHO must act (policy actor), WHAT change is sought (policy action) and BY WHEN (timeline), which is option C. ''Advocates'', ''budget'' and ''resources'' in the other options are strategy inputs, not elements of the objective itself.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Positive non verbal communication includes the following__________?', 'Personal appearance', 'Dancing', 'Laughing', 'Frowning', 'A', 'Per Kozier & Erb''s Fundamentals of Nursing (communication), positive non-verbal communication includes a neat personal appearance/grooming, which conveys professionalism and respect. Frowning (D) is negative, and dancing (B) and laughing (C) are not standard positive professional non-verbal cues in a therapeutic context, so A is correct.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Issues for consideration for advocacy include ____________?', 'Gender based violence', 'Community diagnosis', 'Adult education', 'Political seats', 'A', 'Per Kenya community-health nursing/advocacy guidelines, advocacy addresses social/health injustices needing policy or societal change, and gender-based violence (A) is a classic advocacy issue. Community diagnosis and adult education (B, C) are programme activities, and political seats (D) are not a health-advocacy issue, so A is correct.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is an example of an activity involved in monitoring and evaluation.', 'Registers', 'Outreach', 'Blood Pressure machine', 'Meeting venue', 'A', 'Per Kenya HMIS/community M&E guidelines, monitoring and evaluation is a data/information function, and keeping and reviewing registers (A) is a core M&E activity for tracking indicators. A BP machine (C) and meeting venue (D) are physical resources and outreach (B) is a service-delivery activity, so A is the M&E activity.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is a purpose of monitoring and evaluation?', 'Management', 'Orientation', 'Deployment', 'Employment', 'A', 'Per Kenya health-management/M&E guidelines, the purpose of monitoring and evaluation is to inform management decision-making by tracking progress, ensuring accountability and guiding corrective action (A). Orientation, deployment and employment (B, C, D) are human-resource functions, not the purpose of M&E, so A is correct.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Categories of local resources include _______________?', 'Human Resources, Organizational Resources, Infrastructural Resources, Geographical Resources', 'Human Resources, Organizational Resources, Biological Resources, Infrastructural Resources,', 'Human Resources, Organizational Resources, Biological Resources, Financial Resources', 'Human Resources, Organizational Resources, Infrastructural Resources, Financial Resources', 'D', 'Per community-health resource-mobilisation guidelines, local resources are categorised as human, organizational, infrastructural (material) and financial resources (option D). ''Geographical'' (A) and ''biological'' (B, C) are not standard resource-mobilisation categories, so D lists the correct four categories.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Importance of resource mobilization is to _________________________?', 'Diversify and expand resources', 'Compromise financial sustainability', 'Promote dependency', 'Increase competition', 'A', 'Per community-health resource-mobilisation principles, the importance of resource mobilisation is to diversify and expand the resource base, strengthening sustainability and reducing dependency (A). Compromising sustainability (B), promoting dependency (C) and increasing competition (D) are undesirable outcomes, so A is correct.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Strategies of time management include:', 'Goal setting, Time analysis, prolonged meetings, Delegation, Controlling of interruptions', 'Goal setting, Time analysis, Priority setting, Delegation, Controlling of interruptions', 'Goal setting, prolonged meetings, Priority setting, Delegation, Controlling of interruptions', 'Goal setting, Time analysis, Priority setting, prolonged meetings, Controlling of interruptions', 'B', 'Per nursing management texts (Marquis & Huston), effective time-management strategies are goal setting, time analysis, priority setting, delegation and controlling interruptions (option B). ''Prolonged meetings'' is a recognised time-waster, so every option containing it (A, C, D) is wrong, leaving B.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following categories of patients are automatically exempted:', 'Prisoners, National Youth Service personnel, street children and children above five years of age.', 'Prisoners, National Youth Service personnel, foreigners and children under five years of age', 'Prisoners, National Youth Service personnel, street children and children under five years of age', 'Prisoners, National Youth Service personnel, street children and foreigners', 'C', 'Per Kenya MOH cost-sharing/user-fee exemption policy, automatically exempted groups include prisoners, National Youth Service personnel, street children and children under five years (option C). Children ''above five'' (A) and ''foreigners'' (B, D) are not automatic exemptions, so C is correct.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In advocacy, a constituency refers to;', 'The people in positions of authority', 'The champions who lead the advocacy process', 'The persons affected by the advocacy issue', 'The networks formed to advocate for change', 'C', 'Per community-health advocacy guidelines, a constituency is the people affected by the advocacy issue, on whose behalf advocacy is done (option C). Those in authority (A) are the targets/decision-makers, the champions (B) are the advocates, and networks (D) are advocacy structures, so C is correct.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A manager who is involved in the process of grouping the necessary responsibilities and activities into workable units engages in a role of:', 'Job designing', 'Staffing', 'Scheduling', 'Organizing', 'D', 'Per nursing management texts (Marquis & Huston), grouping necessary responsibilities and activities into workable units is the management function of organizing (structuring work and resources). Job designing (A) shapes individual jobs, staffing (B) fills posts, and scheduling (C) allocates duty times, so D is correct.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The skills of an effective manager are;', 'Conceptual, human, technical', 'Human, communication, technical', 'Technical, political, social', 'Conceptual, social, communication', 'A', 'Per Katz''s classic managerial-skills model (Marquis & Huston), an effective manager needs conceptual, human (interpersonal) and technical skills (option A). The other options substitute non-Katz terms such as communication, political or social skills, so A is correct.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Positive nonverbal communication includes the following__________?', 'Personal appearance', 'Dancing', 'Laughing', 'Frowning', 'A', 'Per Kozier & Erb''s Fundamentals of Nursing, positive non-verbal communication includes appropriate personal appearance/grooming, which signals professionalism and respect (A). Frowning (D) is negative, and dancing (B) and laughing (C) are not standard positive professional non-verbal cues, so A is correct.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is the correct sequence of the steps involved in employee disciplinary procedure?', 'Verbal warning, warning letter, termination, suspension', 'Warning letter, verbal warning, suspension, termination', 'Verbal warning, warning letter, suspension, termination', 'Warning letter, suspension, verbal warning, termination', 'C', 'Per progressive discipline (Marquis & Huston; Kenya HR/labour practice), the sequence is verbal (oral) warning, written warning letter, suspension, then termination as a last resort (option C). Options A, B and D disorder these steps (e.g. placing termination before suspension or the warning letter first), so C is correct.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The assumption in theory X of Douglas McGregor’s is _____________', 'An average human being who has an inherent dislike for work and will avoid it if possible.', 'Employees are seen, as liking work naturally', 'Human beings do not have to be controlled or coerced as long as commitment to the organization is present.', 'Under proper conditions, people will not only accept but also seek responsibility', 'A', 'Per McGregor''s management theory (Marquis & Huston), Theory X assumes the average human inherently dislikes work and will avoid it if possible, requiring control and coercion (option A). Options B, C and D describe Theory Y assumptions (people naturally like work, are self-directed and seek responsibility), so A is correct.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Henry Fayol:', 'Introduced innovations in how jobs were designed and how workers were trained to perform.', 'Identified specific functions of a manger', 'Developed the bureaucratic model', 'Examined motivation from the perspective of why people choose to follow a particular course of action.', 'B', 'Henri Fayol, the father of administrative management, identified the specific functions of a manager (planning, organizing, commanding, coordinating, controlling) and 14 principles (option B). Job design/worker training (A) is Taylor''s scientific management, the bureaucratic model (C) is Weber, and expectancy motivation (D) is others, so B is correct.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Espirit de corps is a principle of management that:', 'Ensures a just working environment for employees', 'Encourages harmony and general good feelings among employees', 'Encourages worker initiative', 'Ensures retention of productive employees', 'B', 'Per Fayol''s 14 principles of management (Marquis & Huston), esprit de corps promotes team spirit, harmony and general good feelings/unity among employees (option B). A just working environment (equity), worker initiative and staff retention are separate principles/concerns, so B is correct.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A capital budget:', 'It is prepared by Nursing ward in charges in consultation with staff', 'Usually coincides with the calendar year', 'Includes the accumulated estimates of operating revenues and expenses', 'Outlines the need for major equipment requiring large sums of money.', 'D', 'Per nursing financial management (Marquis & Huston), a capital budget outlines the need for major equipment, buildings and other long-term assets requiring large sums of money, usually with a multi-year life (option D). Accumulated operating revenues/expenses (C) and calendar-year alignment (B) describe an operating budget, so D is correct.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Managerial functions include;', 'Planning, controlling and staffing', 'Planning, negotiating and liaising', 'Organizing, planning, monitoring', 'Resource allocation, negotiating, monitoring', 'A', 'Per nursing management texts (Marquis & Huston), the core managerial functions are planning, organizing, staffing, directing/leading and controlling; option A (planning, controlling, staffing) lists three genuine functions. Options B, C and D mix in non-core roles such as negotiating, liaising and resource allocation, so A is correct.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following leadership theory states that leaders are born and not made?', 'Trait', 'Charismatic', 'Great man', 'Situational', 'C', 'Per leadership theory (Marquis & Huston), the Great Man theory holds that leaders are born, not made, possessing innate qualities (option C). Trait theory (A) identifies leader characteristics but does not strictly claim they are inborn, charismatic (B) focuses on personal charisma, and situational (D) on context, so C best fits ''born not made''.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Recruitment involves ___________?', 'Advertising a vacancy, short-listing, controlling , induction', 'Advertising a vacancy, short-listing, interviewing, induction.', 'Advertising a vacancy, short-listing, interviewing, controlling', 'Advertising a vacancy, controlling , interviewing, induction', 'B', 'Recruitment and selection is the process of advertising a vacancy, short-listing applicants, interviewing candidates and inducting the successful hire. Option B lists exactly these authentic steps. Options A, C and D each substitute ''controlling'' — a distinct management (monitoring) function, not a recruitment activity. Per Marquis & Huston nursing management and standard HR practice.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Evaluation errors in performance appraisal include _____________________?', 'Formal effect', 'Informal effect', 'Halo effect', 'Double effect', 'C', 'The halo effect is a recognised performance-appraisal rating error in which one strong (favourable) trait causes the rater to score the employee highly across all dimensions. ''Formal effect'', ''informal effect'' and ''double effect'' are not appraisal errors and are distractors. Per Marquis & Huston performance appraisal.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is a stakeholder in occupational health?', 'Refugees', 'Members of the health team', 'Long distance drivers', 'Travellers', 'B', 'In occupational health, the members of the health team are workers exposed to occupational hazards (needlestick, infection, back injury) and are therefore direct stakeholders in an occupational-health programme. Refugees, long-distance drivers and travellers are general/mobile populations, not the defined occupational cohort of the facility. Per Kenya OSH / occupational health guidelines.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Theory Y in management emphasizes on:', 'The organizational goals', 'Motivation', 'Self esteem', 'The goals of an individual.', 'B', 'McGregor''s Theory Y takes an optimistic view of workers as self-directed, responsibility-seeking and internally driven, so management emphasises motivation and empowerment rather than control. Theory X (not Y) focuses on close control toward organisational goals; self-esteem and individual goals are not the defining emphasis. Per Marquis & Huston management theory.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Barriers to effective delegation include all the following EXCEPT?', 'Reluctance to delegate', 'Lack of confidence in subordinates', 'Inability to plan', 'Employees values and interests', 'D', 'Recognised barriers to effective delegation are the manager''s reluctance to delegate, lack of confidence/trust in subordinates and inability to plan or organise work. Employees'' values and interests are a factor used to match tasks to the right staff, not a barrier — hence the EXCEPT answer. Per Marquis & Huston nursing management.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The manager stresses the need for employees to follow orders and instructions and not from anyone else. which of the following principles does he refer to?', 'Scalar chain', 'Discipline', 'Unity of command', 'Order', 'C', 'Fayol''s principle of unity of command holds that each employee should receive orders and be accountable to only one superior, exactly as the manager describes. Scalar chain is the vertical line of authority, discipline concerns obedience/agreements, and order concerns arrangement of people/resources. Per Fayol''s 14 principles (Marquis & Huston).', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The statement “The Holy spirit Medical center aims to provide patient centred care in a total healing environment” refers to which of the following', 'Vision', 'Goal', 'Philosophy', 'Mission', 'D', 'A mission statement declares the organisation''s present core purpose and what it aims to do now (''aims to provide patient-centred care in a total healing environment''). A vision describes the desired future state, a goal is a measurable target, and a philosophy states underlying values/beliefs. Per Marquis & Huston strategic planning.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is NOT an advantage of Functional nursing model', 'It is economical', 'It is time saving', 'Easy to organize', 'Cultivates team spirit', 'D', 'Functional (task-oriented) nursing is economical, time-saving and easy to organise, but because staff perform isolated tasks it fragments care and does NOT cultivate team spirit — that benefit belongs to team/modular nursing. Hence D is the correct EXCEPT answer. Per Marquis & Huston care delivery models.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The leadership theory states that leaders are born and not made is___________?', 'Trait', 'Charismatic', 'Great man', 'Situational', 'C', 'The Great Man theory asserts that leaders are born, not made, possessing innate leadership qualities from birth. Trait theory catalogues characteristics of effective leaders but does not insist they are inborn, charismatic theory centres on personal magnetism, and situational theory ties leadership to context. Per Marquis & Huston leadership theory.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The function of a manager that ensures effective and appropriate use of resources is:', 'Organizing', 'Planning', 'Controlling', 'Implementation', 'C', 'Controlling is the management function that measures performance against standards and ensures resources are used effectively and appropriately through monitoring and corrective action. Planning sets objectives, organising arranges resources, and implementation executes plans. Per Marquis & Huston nursing management.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Some principles of management include:', 'Priority setting, Evaluating progress, minimal breaks', 'Time analysis, goal setting, delegation', 'Avoiding delegation, time analysis, controlling interruptions', 'Time analysis, goal setting, minimal breaks', 'B', 'Sound time/management principles include time analysis, goal setting and delegation, all of which appear together in option B. The other options contain poor practices such as ''minimal breaks'' and ''avoiding delegation'', which impair rather than improve managerial effectiveness. Per Marquis & Huston nursing management.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The advantages of decentralization in management include:', 'Increased level of decision making and flexibility', 'Quick and better decision making', 'Flexibility of staff and decreased bureaucracy', 'Reduced cost and avoids duplication of efforts', 'B', 'Decentralisation pushes decision-making authority downward, so decisions are made quicker and better by those closest to the situation. Option B captures this primary advantage most precisely; the other options blend it with less accurate or overstated claims. Per Marquis & Huston nursing management.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following statement is true regarding evaluator’s rating errors', 'Halo Effect- The ratter only recalls or uses recent data', 'Recency Effect- The ratter assumes that if the person does well in several known areas, he or she will do well in all areas', 'Sunflower effect-Ratter scores all the employees high because they are a great team', 'Central tendency effect- Different ratters tend to score leniently or strictly.', 'C', 'Only option C correctly pairs error and definition: the sunflower effect is rating all group members high because they are perceived as a great team. A, B and D mislabel the definitions (recency = using only recent data; halo = one good area assumed across all; central tendency = clustering scores at the middle). Per Marquis & Huston performance appraisal.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When preparing staff schedules, the nurse manager should:', 'Determine hours of minimum and maximum workload before preparing the schedule', 'Avoid displaying the schedule early to minimize complaints from the staff', 'Avoid reviewing the schedule as the week progresses', 'Never consider the patient care needs', 'A', 'Effective staff scheduling begins by determining the minimum and maximum workload/staffing requirements dictated by patient care needs before drafting the roster. The other options — concealing the schedule, not reviewing it, and ignoring patient needs — are all poor scheduling practices. Per Marquis & Huston staffing/scheduling.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Disasters of geographical origin includes;', 'Tsunamis, hurricanes, volcanic eruptions', 'Fire, earthquakes, acid rain', 'Cyclones, floods, desertification', 'Volcanic eruptions, explosions, fire', 'A', 'Disasters of geophysical/geographical origin are natural earth- and weather-driven events such as tsunamis, hurricanes and volcanic eruptions, grouped in option A. The other options mix in man-made/technological hazards (fire, explosions) and environmental degradation (acid rain, desertification), which are not classified as geographical disasters. Per WHO / Kenya disaster management classification.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Principles of time management include:', 'Goal setting, priority setting, controlling interruptions', 'Goal setting, setting priorities, organization.', 'Organization, time analysis, goal setting', 'Setting priorities, organization, controlling interruptions', 'A', 'Core time-management principles are goal setting, priority setting and controlling interruptions, all present in option A. While other options list some valid elements, A best combines three recognised principles without redundancy for the stem. Per Marquis & Huston nursing management.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Main managerial functions include;', 'Planning, controlling, organizing and staffing', 'Planning, liaising organizing and staffing', 'Organizing, planning, monitoring, staffing', 'Planning, controlling, negotiating, monitoring', 'A', 'The main managerial functions are planning, organising, staffing, directing/leading and controlling; option A lists four authentic ones (planning, controlling, organising, staffing). The other options insert non-core activities such as liaising, negotiating and monitoring. Per Marquis & Huston nursing management.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The main difference between a manager and a leader is that, a leader____;', 'Works with and through people to achieve organizational goals.', 'Works effectively and efficiently', 'Has formal authority and responsibility', 'Is able to influence people.', 'D', 'Leadership is fundamentally the ability to influence people toward achieving goals, and this influence — not formal authority — distinguishes a leader from a manager. Working through people and being efficient can describe both roles, while formal authority/responsibility specifically characterises the manager. Per Marquis & Huston leadership theory.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following principle of management explains systematic retention of power at higher levels of an organisation', 'Decentralisation', 'Centralisation', 'Coercive authority', 'Unity of command', 'B', 'Centralisation is the systematic retention/concentration of decision-making authority at the higher (top) levels of an organisation. Decentralisation is its opposite (dispersal of authority downward), coercive authority is power through threat, and unity of command concerns reporting to one superior. Per Fayol''s principles (Marquis & Huston).', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lose-lose strategy of conflict management;', 'Leads to a greater conflict', 'The conflicting parties come up with something neutral', 'One party achieves its desire at the expense of the other', 'The reason for conflict is addressed', 'A', 'In a lose-lose conflict strategy neither party meets its needs, leaving both dissatisfied so the underlying conflict typically persists or escalates. Win-lose is where one party gains at the other''s expense, compromise reaches something neutral, and win-win/collaboration addresses the root cause. Per Marquis & Huston conflict management.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
